window.Handbook.register({"id":"ch167","pages":[{"n":1178,"html":"<span class=\"bookmark-anchor\" id=\"b981\"><\/span><h2 class=\"book-heading\">第167 章编写i2c client 代码（方法2）<\/h2>\n<p class=\"body-copy\">本章使用C 文件实现i2c client 代码并与上一章编写的i2c driver 框架进行匹配。需要注意的是，主流开发方式是使用设备树编写i2c client 而不是使用C 文件编写i2c client。<\/p>\n<span class=\"bookmark-anchor\" id=\"b982\"><\/span><h3 class=\"book-heading\">167.1API 函数介绍<\/h3>\n<span class=\"bookmark-anchor\" id=\"b983\"><\/span><h4 class=\"book-heading\">167.1.1 i2c_get_adapter 函数<\/h4>\n<p class=\"body-copy\">i2c_get_adapter()函数的主要作用是根据给定的i2c 控制器编号nr 从i2c_adapter_idr 中查找对应的i2c_adapter 结构体，该函数定义在drivers/i2c/i2c-core-base.c 文件中，具体内容如代码清单167.1 所示。<\/p>\n<p class=\"caption\">代码清单167.1<\/p>\n<div class=\"code-box\" data-start=\"1\" data-end=\"24\" data-contiguous=\"true\"><div class=\"code-bar\"><span>代码清单<\/span><button type=\"button\" class=\"copy-code\">复制代码<\/button><\/div><pre tabindex=\"0\"><code><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">1<\/span><span class=\"source-line\">struct i2c_adapter *i2c_get_adapter(int nr)<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">2<\/span><span class=\"source-line\">{<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">3<\/span><span class=\"source-line\">    struct i2c_adapter *adapter;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">4<\/span><span class=\"source-line\"><\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">5<\/span><span class=\"source-line\">    //获取core_lock 锁，以防止其他线程同时访问i2c_adapter_idr<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">6<\/span><span class=\"source-line\">    mutex_lock(&amp;core_lock);<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">7<\/span><span class=\"source-line\"><\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">8<\/span><span class=\"source-line\">    //在i2c_adapter_idr 中查找指定编号的控制器<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">9<\/span><span class=\"source-line\"><\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">10<\/span><span class=\"source-line\">    adapter = idr_find(&amp;i2c_adapter_idr, nr);<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">11<\/span><span class=\"source-line\">    if (!adapter)<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">12<\/span><span class=\"source-line\">        goto exit;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">13<\/span><span class=\"source-line\"><\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">14<\/span><span class=\"source-line\">    //尝试获取控制器所属模块的引用计数<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">15<\/span><span class=\"source-line\">    if (try_module_get(adapter-&gt;owner))<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">16<\/span><span class=\"source-line\">        //增加控制器device 的引用计数<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">17<\/span><span class=\"source-line\">        get_device(&amp;adapter-&gt;dev);<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">18<\/span><span class=\"source-line\">    else<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">19<\/span><span class=\"source-line\">        adapter = NULL;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">20<\/span><span class=\"source-line\"><\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">21<\/span><span class=\"source-line\">exit:<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">22<\/span><span class=\"source-line\">    //释放i2c_adapter_idr 中的锁<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">23<\/span><span class=\"source-line\">    mutex_unlock(&amp;core_lock);<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">24<\/span><span class=\"source-line\"><\/span><\/span><\/code><\/pre><p class=\"code-note\">原书第 1178 页 · 行号不参与复制 · <button type=\"button\" data-original=\"1178\">核对原页<\/button><\/p><\/div>"},{"n":1179,"html":"<div class=\"code-box\" data-start=\"25\" data-end=\"25\" data-contiguous=\"true\"><div class=\"code-bar\"><span>代码清单 · 跨页续接<\/span><button type=\"button\" class=\"copy-code\">复制代码<\/button><\/div><pre tabindex=\"0\"><code><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">25<\/span><span class=\"source-line\">}    return adapter;<\/span><\/span><\/code><\/pre><p class=\"code-note\">原书第 1179 页 · 行号不参与复制 · <button type=\"button\" data-original=\"1179\">核对原页<\/button><\/p><\/div>\n<span class=\"bookmark-anchor\" id=\"b984\"><\/span><h4 class=\"book-heading\">167.1.2 i2c_put_adapter 函数<\/h4>\n<p class=\"body-copy\">当驱动卸载时使用i2c_put_adapter()函数释放i2c_adapter 结构体，i2c_put_adapter()函数定义在drivers/i2c/i2c-core-base.c 文件中，具体内容如代码清单167.2 所示。<\/p>\n<p class=\"caption\">代码清单167.2<\/p>\n<div class=\"code-box\" data-start=\"1\" data-end=\"9\" data-contiguous=\"true\"><div class=\"code-bar\"><span>代码清单<\/span><button type=\"button\" class=\"copy-code\">复制代码<\/button><\/div><pre tabindex=\"0\"><code><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">1<\/span><span class=\"source-line\">void i2c_put_adapter(struct i2c_adapter *adap)<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">2<\/span><span class=\"source-line\">{<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">3<\/span><span class=\"source-line\">    //如果adap 指针为NULL，直接返回<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">4<\/span><span class=\"source-line\">    if (!adap)<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">5<\/span><span class=\"source-line\">        return;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">6<\/span><span class=\"source-line\"><\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">7<\/span><span class=\"source-line\">    put_device(&amp;adap-&gt;dev);    //调用put_device()函数释放i2c_adapter 设备<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">8<\/span><span class=\"source-line\">    module_put(adap-&gt;owner);    //减少i2c_adapter 所属模块的引用计数<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">9<\/span><span class=\"source-line\">}<\/span><\/span><\/code><\/pre><p class=\"code-note\">原书第 1179 页 · 行号不参与复制 · <button type=\"button\" data-original=\"1179\">核对原页<\/button><\/p><\/div>\n<span class=\"bookmark-anchor\" id=\"b985\"><\/span><h4 class=\"book-heading\">167.1.3 i2c_new_device 函数<\/h4>\n<p class=\"body-copy\">i2c_new_device()函数用于实例化一个i2c 设备，该函数定义在drivers/i2c/i2c-core-base.c 文件中，具体内容如代码清单167.3 所示。<\/p>\n<p class=\"caption\">代码清单167.3<\/p>\n<div class=\"code-box\" data-start=\"1\" data-end=\"18\" data-contiguous=\"true\"><div class=\"code-bar\"><span>代码清单<\/span><button type=\"button\" class=\"copy-code\">复制代码<\/button><\/div><pre tabindex=\"0\"><code><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">1<\/span><span class=\"source-line\">struct i2c_client *i2c_new_device(struct i2c_adapter *adap, struct i2c_board_info const *info)<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">2<\/span><span class=\"source-line\">{<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">3<\/span><span class=\"source-line\">        struct i2c_client       *client;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">4<\/span><span class=\"source-line\">        int        status;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">5<\/span><span class=\"source-line\"><\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">6<\/span><span class=\"source-line\">        //分配i2c_client 结构体空间<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">7<\/span><span class=\"source-line\">        client = kzalloc(sizeof *client, GFP_KERNEL);<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">8<\/span><span class=\"source-line\">        if (!client)<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">9<\/span><span class=\"source-line\">                return NULL;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">10<\/span><span class=\"source-line\"><\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">11<\/span><span class=\"source-line\">        //设置i2c_client 的控制器指针，将传入的i2c_adapter 指针保存到i2c_client 的adapter 字段中<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">12<\/span><span class=\"source-line\">        client-&gt;adapter = adap;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">13<\/span><span class=\"source-line\"><\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">14<\/span><span class=\"source-line\">        //从i2c_board_info 结构体中拷贝相关信息到i2c_client<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">15<\/span><span class=\"source-line\">        client-&gt;dev.platform_data = info-&gt;platform_data;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">16<\/span><span class=\"source-line\">        client-&gt;flags = info-&gt;flags;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">17<\/span><span class=\"source-line\">        client-&gt;addr = info-&gt;addr;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">18<\/span><span class=\"source-line\">        client-&gt;init_irq = info-&gt;irq;<\/span><\/span><\/code><\/pre><p class=\"code-note\">原书第 1179 页 · 行号不参与复制 · <button type=\"button\" data-original=\"1179\">核对原页<\/button><\/p><\/div>"},{"n":1180,"html":"<div class=\"code-box\" data-start=\"19\" data-end=\"62\" data-contiguous=\"true\"><div class=\"code-bar\"><span>代码清单 · 跨页续接<\/span><button type=\"button\" class=\"copy-code\">复制代码<\/button><\/div><pre tabindex=\"0\"><code><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">19<\/span><span class=\"source-line\">        if (!client-&gt;init_irq)<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">20<\/span><span class=\"source-line\">                client-&gt;init_irq = i2c_dev_irq_from_resources(info-&gt;resources,<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">21<\/span><span class=\"source-line\">                                                        info-&gt;num_resources);<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">22<\/span><span class=\"source-line\">        client-&gt;irq = client-&gt;init_irq;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">23<\/span><span class=\"source-line\">        strlcpy(client-&gt;name, info-&gt;type, sizeof(client-&gt;name));<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">24<\/span><span class=\"source-line\"><\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">25<\/span><span class=\"source-line\">        //检查地址是否有效<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">26<\/span><span class=\"source-line\">        status = i2c_check_addr_validity(client-&gt;addr, client-&gt;flags);<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">27<\/span><span class=\"source-line\">        if (status) {<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">28<\/span><span class=\"source-line\">                dev_err(&amp;adap-&gt;dev, &quot;Invalid %d-bit i2c address 0x%02hx\\n&quot;,<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">29<\/span><span class=\"source-line\">                        client-&gt;flags &amp; i2c_CLIENT_TEN ? 10 : 7, client-&gt;addr);<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">30<\/span><span class=\"source-line\">                goto out_err_silent;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">31<\/span><span class=\"source-line\">        }<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">32<\/span><span class=\"source-line\"><\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">33<\/span><span class=\"source-line\">        //检查地址是否已被其他设备占用<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">34<\/span><span class=\"source-line\">        status = i2c_check_addr_ex(adap, i2c_encode_flags_to_addr(client));<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">35<\/span><span class=\"source-line\">        if (status)<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">36<\/span><span class=\"source-line\">                dev_err(&amp;adap-&gt;dev,<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">37<\/span><span class=\"source-line\">                        &quot;%d i2c clients have been registered at 0x%02x&quot;,<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">38<\/span><span class=\"source-line\">                        status, client-&gt;addr);<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">39<\/span><span class=\"source-line\"><\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">40<\/span><span class=\"source-line\">        //设置i2c_client 的设备信息<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">41<\/span><span class=\"source-line\">        client-&gt;dev.parent = &amp;client-&gt;adapter-&gt;dev;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">42<\/span><span class=\"source-line\">        client-&gt;dev.bus = &amp;i2c_bus_type;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">43<\/span><span class=\"source-line\">        client-&gt;dev.type = &amp;i2c_client_type;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">44<\/span><span class=\"source-line\">        client-&gt;dev.of_node = of_node_get(info-&gt;of_node);<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">45<\/span><span class=\"source-line\">        client-&gt;dev.fwnode = info-&gt;fwnode;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">46<\/span><span class=\"source-line\">        i2c_dev_set_name(adap, client, info, status);<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">47<\/span><span class=\"source-line\"><\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">48<\/span><span class=\"source-line\">        //如果有设备属性，添加到设备<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">49<\/span><span class=\"source-line\">        if (info-&gt;properties) {<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">50<\/span><span class=\"source-line\">                status = device_add_properties(&amp;client-&gt;dev, info-&gt;properties);<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">51<\/span><span class=\"source-line\">                if (status) {<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">52<\/span><span class=\"source-line\">                        dev_err(&amp;adap-&gt;dev,<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">53<\/span><span class=\"source-line\">                               &quot;Failed to add properties to client %s: %d\\n&quot;,<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">54<\/span><span class=\"source-line\">                               client-&gt;name, status);<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">55<\/span><span class=\"source-line\">                        goto out_err_put_of_node;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">56<\/span><span class=\"source-line\">                }<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">57<\/span><span class=\"source-line\">        }<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">58<\/span><span class=\"source-line\"><\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">59<\/span><span class=\"source-line\">        //注册设备<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">60<\/span><span class=\"source-line\">        status = device_register(&amp;client-&gt;dev);<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">61<\/span><span class=\"source-line\">        if (status)<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">62<\/span><span class=\"source-line\">                goto out_free_props;<\/span><\/span><\/code><\/pre><p class=\"code-note\">原书第 1180 页 · 行号不参与复制 · <button type=\"button\" data-original=\"1180\">核对原页<\/button><\/p><\/div>"},{"n":1181,"html":"<div class=\"code-box\" data-start=\"63\" data-end=\"77\" data-contiguous=\"true\"><div class=\"code-bar\"><span>代码清单 · 跨页续接<\/span><button type=\"button\" class=\"copy-code\">复制代码<\/button><\/div><pre tabindex=\"0\"><code><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">63<\/span><span class=\"source-line\"><\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">64<\/span><span class=\"source-line\">        dev_dbg(&amp;adap-&gt;dev, &quot;client [%s] registered with bus id %s\\n&quot;,<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">65<\/span><span class=\"source-line\">                client-&gt;name, dev_name(&amp;client-&gt;dev));<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">66<\/span><span class=\"source-line\"><\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">67<\/span><span class=\"source-line\">        return client;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">68<\/span><span class=\"source-line\"><\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">69<\/span><span class=\"source-line\">out_free_props:<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">70<\/span><span class=\"source-line\">        if (info-&gt;properties)<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">71<\/span><span class=\"source-line\">                device_remove_properties(&amp;client-&gt;dev);<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">72<\/span><span class=\"source-line\">out_err_put_of_node:<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">73<\/span><span class=\"source-line\">        of_node_put(info-&gt;of_node);<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">74<\/span><span class=\"source-line\">out_err_silent:<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">75<\/span><span class=\"source-line\">        kfree(client);<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">76<\/span><span class=\"source-line\">        return NULL;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">77<\/span><span class=\"source-line\">}<\/span><\/span><\/code><\/pre><p class=\"code-note\">原书第 1181 页 · 行号不参与复制 · <button type=\"button\" data-original=\"1181\">核对原页<\/button><\/p><\/div>\n<span class=\"bookmark-anchor\" id=\"b986\"><\/span><h4 class=\"book-heading\">167.1.4 i2c_board_info 结构体<\/h4>\n<p class=\"body-copy\">i2c_new_device()函数会传入一个i2c_board_info 类型的结构体，该结构体描述了i2c 设备的静态信息，如设备类型、地址、名称等，该结构体定义在include/linux/i2c.h 文件中，具体内容如代码清单167.4 所示。<\/p>\n<p class=\"caption\">代码清单167.4<\/p>\n<div class=\"code-box\" data-start=\"1\" data-end=\"13\" data-contiguous=\"true\"><div class=\"code-bar\"><span>代码清单<\/span><button type=\"button\" class=\"copy-code\">复制代码<\/button><\/div><pre tabindex=\"0\"><code><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">1<\/span><span class=\"source-line\">struct i2c_board_info {<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">2<\/span><span class=\"source-line\">    char type[i2c_NAME_SIZE];    // i2c 设备的类型名称，最大长度为i2c_NAME_SIZE<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">3<\/span><span class=\"source-line\">    unsigned short flags;    // i2c 设备的标志位，用于指定设备的特殊属性<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">4<\/span><span class=\"source-line\">    unsigned short addr;    // i2c 设备的地址<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">5<\/span><span class=\"source-line\">    const char *dev_name;    // i2c 设备的设备名称<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">6<\/span><span class=\"source-line\">    void *platform_data;    // i2c 设备的平台数据，可为NULL<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">7<\/span><span class=\"source-line\">    struct device_node *of_node;    // i2c 设备节点在设备树中的节点指针<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">8<\/span><span class=\"source-line\">    struct fwnode_handle *fwnode;    // i2c 设备节点在ACPI 中的fwnode 句柄<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">9<\/span><span class=\"source-line\">    const struct property_entry *properties;    // i2c 设备的属性列表<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">10<\/span><span class=\"source-line\">    const struct resource *resources;    // i2c 设备使用的资源列表<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">11<\/span><span class=\"source-line\">    unsigned int num_resources;    // i2c 设备使用的资源数量<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">12<\/span><span class=\"source-line\">    int irq;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">13<\/span><span class=\"source-line\">};<\/span><\/span><\/code><\/pre><p class=\"code-note\">原书第 1181 页 · 行号不参与复制 · <button type=\"button\" data-original=\"1181\">核对原页<\/button><\/p><\/div>\n<span class=\"bookmark-anchor\" id=\"b987\"><\/span><h3 class=\"book-heading\">167.2 驱动程序的编写<\/h3>\n<p class=\"body-copy\">本实验代码存储在网盘iTOP-RK3568 开发板\\07_学习教程配套资料\\03_Linux 驱动配套资料\\04_Linux 驱动程序\\103_ft5x06_02\\路径下。<\/p>"},{"n":1182,"html":"<p class=\"body-copy\">本实验使用C 文件编写i2c client 代码，实验代码ft5x06_device.c 如代码清单167.5 所示。<\/p>\n<p class=\"caption\">代码清单167.5<\/p>\n<div class=\"code-box\" data-start=\"1\" data-end=\"41\" data-contiguous=\"true\"><div class=\"code-bar\"><span>代码清单<\/span><button type=\"button\" class=\"copy-code\">复制代码<\/button><\/div><pre tabindex=\"0\"><code><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">1<\/span><span class=\"source-line\">#include &lt;linux/module.h&gt;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">2<\/span><span class=\"source-line\">#include &lt;linux/init.h&gt;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">3<\/span><span class=\"source-line\">#include &lt;linux/i2c.h&gt;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">4<\/span><span class=\"source-line\"><\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">5<\/span><span class=\"source-line\">//定义一个i2c_adapter 结构体指针<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">6<\/span><span class=\"source-line\">struct i2c_adapter *i2c_ada;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">7<\/span><span class=\"source-line\"><\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">8<\/span><span class=\"source-line\">//定义i2c_board_info 结构体数组，用于描述ft5x06 设备<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">9<\/span><span class=\"source-line\">static struct i2c_board_info ft5x06[] = {<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">10<\/span><span class=\"source-line\">    {<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">11<\/span><span class=\"source-line\">        .type = &quot;my-ft5x06&quot;,<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">12<\/span><span class=\"source-line\">        .addr = 0x38, // ft5x06 设备的i2c 地址<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">13<\/span><span class=\"source-line\">    },<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">14<\/span><span class=\"source-line\">};<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">15<\/span><span class=\"source-line\"><\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">16<\/span><span class=\"source-line\">//驱动的初始化函数<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">17<\/span><span class=\"source-line\">static int ft5x06_client_init(void)<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">18<\/span><span class=\"source-line\">{<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">19<\/span><span class=\"source-line\">    //获取i2c 控制器<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">20<\/span><span class=\"source-line\">    i2c_ada = i2c_get_adapter(1);<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">21<\/span><span class=\"source-line\">    if (!i2c_ada)<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">22<\/span><span class=\"source-line\">    {<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">23<\/span><span class=\"source-line\">        printk(KERN_ERR &quot;Failed to get i2c adapter\\n&quot;);<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">24<\/span><span class=\"source-line\">        return -ENODEV;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">25<\/span><span class=\"source-line\">    }<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">26<\/span><span class=\"source-line\"><\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">27<\/span><span class=\"source-line\">    //注册ft5x06 设备<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">28<\/span><span class=\"source-line\">    i2c_new_device(i2c_ada, ft5x06);<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">29<\/span><span class=\"source-line\"><\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">30<\/span><span class=\"source-line\">    return 0;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">31<\/span><span class=\"source-line\">}<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">32<\/span><span class=\"source-line\"><\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">33<\/span><span class=\"source-line\">//驱动的退出函数<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">34<\/span><span class=\"source-line\">static void ft5x06_client_exit(void)<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">35<\/span><span class=\"source-line\">{<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">36<\/span><span class=\"source-line\">     //释放i2c 控制器<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">37<\/span><span class=\"source-line\">    i2c_put_adapter(i2c_ada);<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">38<\/span><span class=\"source-line\">}<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">39<\/span><span class=\"source-line\"><\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">40<\/span><span class=\"source-line\">//驱动的初始化和退出入口函数<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">41<\/span><span class=\"source-line\">module_init(ft5x06_client_init);<\/span><\/span><\/code><\/pre><p class=\"code-note\">原书第 1182 页 · 行号不参与复制 · <button type=\"button\" data-original=\"1182\">核对原页<\/button><\/p><\/div>"},{"n":1183,"html":"<div class=\"code-box\" data-start=\"42\" data-end=\"44\" data-contiguous=\"true\"><div class=\"code-bar\"><span>代码清单 · 跨页续接<\/span><button type=\"button\" class=\"copy-code\">复制代码<\/button><\/div><pre tabindex=\"0\"><code><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">42<\/span><span class=\"source-line\">module_exit(ft5x06_client_exit);<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">43<\/span><span class=\"source-line\"><\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">44<\/span><span class=\"source-line\">MODULE_LICENSE(&quot;GPL&quot;);<\/span><\/span><\/code><\/pre><p class=\"code-note\">原书第 1183 页 · 行号不参与复制 · <button type=\"button\" data-original=\"1183\">核对原页<\/button><\/p><\/div>\n<p class=\"body-copy\">使用C 文件编写i2c client 与使用设备树编写i2c client 与i2c driver 匹配方式不同，所以并不能直接使用上一章节编写的i2c driver，需要对驱动程序进行简单的修改，修改完成以后的实验代码ft5x06_driver.c 驱动程序如代码清单167.6 所示。<\/p>\n<p class=\"caption\">代码清单167.6<\/p>\n<div class=\"code-box\" data-start=\"1\" data-end=\"35\" data-contiguous=\"true\"><div class=\"code-bar\"><span>代码清单<\/span><button type=\"button\" class=\"copy-code\">复制代码<\/button><\/div><pre tabindex=\"0\"><code><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">1<\/span><span class=\"source-line\">#include &lt;linux/init.h&gt;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">2<\/span><span class=\"source-line\">#include &lt;linux/module.h&gt;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">3<\/span><span class=\"source-line\">#include &lt;linux/i2c.h&gt;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">4<\/span><span class=\"source-line\">#include &lt;linux/of_device.h&gt;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">5<\/span><span class=\"source-line\"><\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">6<\/span><span class=\"source-line\">// ft5x06 设备的初始化函数<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">7<\/span><span class=\"source-line\">int ft5x06_probe(struct i2c_client *client, const struct i2c_device_id *id) {<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">8<\/span><span class=\"source-line\">    printk(&quot;This is ft5x06 probe\\n&quot;);<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">9<\/span><span class=\"source-line\">    return 0;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">10<\/span><span class=\"source-line\">}<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">11<\/span><span class=\"source-line\"><\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">12<\/span><span class=\"source-line\">// ft5x06 设备的移除函数<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">13<\/span><span class=\"source-line\">int ft5x06_remove(struct i2c_client *client) {<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">14<\/span><span class=\"source-line\">    return 0;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">15<\/span><span class=\"source-line\">}<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">16<\/span><span class=\"source-line\"><\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">17<\/span><span class=\"source-line\">//定义i2c_device_id 结构体数组，用于标识ft5x06 设备<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">18<\/span><span class=\"source-line\">static const struct i2c_device_id ft5x06_id[] = {<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">19<\/span><span class=\"source-line\">    { &quot;my-ft5x06&quot;, 0 },<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">20<\/span><span class=\"source-line\">    { }<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">21<\/span><span class=\"source-line\">};<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">22<\/span><span class=\"source-line\">MODULE_DEVICE_TABLE(i2c, ft5x06_id);<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">23<\/span><span class=\"source-line\"><\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">24<\/span><span class=\"source-line\">//定义i2c_driver 结构体，描述ft5x06 设备驱动<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">25<\/span><span class=\"source-line\">static struct i2c_driver ft5x06_driver = {<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">26<\/span><span class=\"source-line\">    .driver = {<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">27<\/span><span class=\"source-line\">        .name   = &quot;my-ft5x06&quot;,<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">28<\/span><span class=\"source-line\">        .owner  = THIS_MODULE,<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">29<\/span><span class=\"source-line\">    },<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">30<\/span><span class=\"source-line\">    .probe      = ft5x06_probe,<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">31<\/span><span class=\"source-line\">    .remove     = ft5x06_remove,<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">32<\/span><span class=\"source-line\">    .id_table   = ft5x06_id,<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">33<\/span><span class=\"source-line\">};<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">34<\/span><span class=\"source-line\"><\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">35<\/span><span class=\"source-line\">//驱动初始化函数<\/span><\/span><\/code><\/pre><p class=\"code-note\">原书第 1183 页 · 行号不参与复制 · <button type=\"button\" data-original=\"1183\">核对原页<\/button><\/p><\/div>"},{"n":1184,"html":"<div class=\"code-box\" data-start=\"36\" data-end=\"55\" data-contiguous=\"true\"><div class=\"code-bar\"><span>代码清单 · 跨页续接<\/span><button type=\"button\" class=\"copy-code\">复制代码<\/button><\/div><pre tabindex=\"0\"><code><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">36<\/span><span class=\"source-line\">static int __init ft5x06_driver_init(void) {<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">37<\/span><span class=\"source-line\">    int ret;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">38<\/span><span class=\"source-line\">    //注册i2c 设备驱动<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">39<\/span><span class=\"source-line\">    ret = i2c_add_driver(&amp;ft5x06_driver);<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">40<\/span><span class=\"source-line\">    if (ret &lt; 0) {<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">41<\/span><span class=\"source-line\">        printk(&quot;i2c_add_driver is error\\n&quot;);<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">42<\/span><span class=\"source-line\">        return ret;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">43<\/span><span class=\"source-line\">    }<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">44<\/span><span class=\"source-line\">    return 0;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">45<\/span><span class=\"source-line\">}<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">46<\/span><span class=\"source-line\"><\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">47<\/span><span class=\"source-line\">//驱动退出函数<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">48<\/span><span class=\"source-line\">static void __exit ft5x06_driver_exit(void) {<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">49<\/span><span class=\"source-line\">    //注销i2c 设备驱动<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">50<\/span><span class=\"source-line\">    i2c_del_driver(&amp;ft5x06_driver);<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">51<\/span><span class=\"source-line\">}<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">52<\/span><span class=\"source-line\"><\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">53<\/span><span class=\"source-line\">module_init(ft5x06_driver_init);<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">54<\/span><span class=\"source-line\">module_exit(ft5x06_driver_exit);<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">55<\/span><span class=\"source-line\">MODULE_LICENSE(&quot;GPL&quot;);<\/span><\/span><\/code><\/pre><p class=\"code-note\">原书第 1184 页 · 行号不参与复制 · <button type=\"button\" data-original=\"1184\">核对原页<\/button><\/p><\/div>\n<span class=\"bookmark-anchor\" id=\"b988\"><\/span><h3 class=\"book-heading\">167.3 运行测试<\/h3>\n<span class=\"bookmark-anchor\" id=\"b989\"><\/span><h4 class=\"book-heading\">167.3.1 编译驱动程序<\/h4>\n<p class=\"body-copy\">在ft5x06_device.c 代码同一目录下创建Makefile 文件，如图167.1 所示。<\/p>\n<figure class=\"book-figure\"><button type=\"button\" class=\"zoom-image\" aria-label=\"放大图167.1\"><img src=\"3568阅读资源/figures/p1184-fig01.webp\" loading=\"lazy\" decoding=\"async\" alt=\"图167.1\" width=\"974\" height=\"66\"><\/button><figcaption>图167.1 · 点击放大<\/figcaption><\/figure>\n<p class=\"body-copy\">Makefile 文件内容如代码清单167.7 所示。<\/p>\n<p class=\"caption\">代码清单167.7<\/p>\n<div class=\"code-box\" data-start=\"1\" data-end=\"9\" data-contiguous=\"true\"><div class=\"code-bar\"><span>Makefile<\/span><button type=\"button\" class=\"copy-code\">复制代码<\/button><\/div><pre tabindex=\"0\"><code><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">1<\/span><span class=\"source-line\">export ARCH=arm64#设置平台架构<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">2<\/span><span class=\"source-line\">export CROSS_COMPILE=aarch64-linux-gnu-#交叉编译器前缀<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">3<\/span><span class=\"source-line\">obj-m += ft5x06_device.o    #此处要和你的驱动源文件同名<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">4<\/span><span class=\"source-line\">KDIR :=/home/topeet/Linux/linux_sdk/kernel    #这里是你的内核目录<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">5<\/span><span class=\"source-line\">PWD ?= $(shell pwd)<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">6<\/span><span class=\"source-line\">all:<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">7<\/span><span class=\"source-line\">\tmake -C $(KDIR) M=$(PWD) modules    #make 操作<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">8<\/span><span class=\"source-line\">clean:<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">9<\/span><span class=\"source-line\">\tmake -C $(KDIR) M=$(PWD) clean    #make clean 操作<\/span><\/span><\/code><\/pre><p class=\"code-note\">原书第 1184 页 · 行号不参与复制 · <button type=\"button\" data-original=\"1184\">核对原页<\/button><\/p><\/div>"},{"n":1185,"html":"<p class=\"body-copy\">在存放ft5x06_device.c 和Makefile 文件目录下使用make 命令编译驱动程序，编译完成如图167.2 所示。<\/p>\n<figure class=\"book-figure\"><button type=\"button\" class=\"zoom-image\" aria-label=\"放大图167.2\"><img src=\"3568阅读资源/figures/p1185-fig01.webp\" loading=\"lazy\" decoding=\"async\" alt=\"图167.2\" width=\"974\" height=\"188\"><\/button><figcaption>图167.2 · 点击放大<\/figcaption><\/figure>\n<p class=\"body-copy\">编译成功后得到ft5x06_driver.ko 文件，如图167.3 所示。<\/p>\n<figure class=\"book-figure\"><button type=\"button\" class=\"zoom-image\" aria-label=\"放大图167.3\"><img src=\"3568阅读资源/figures/p1185-fig02.webp\" loading=\"lazy\" decoding=\"async\" alt=\"图167.3\" width=\"974\" height=\"81\"><\/button><figcaption>图167.3 · 点击放大<\/figcaption><\/figure>\n<p class=\"body-copy\">然后在ft5x06_driver.c 代码同一目录下创建Makefile 文件，如图167.4 所示。<\/p>\n<figure class=\"book-figure\"><button type=\"button\" class=\"zoom-image\" aria-label=\"放大图167.4\"><img src=\"3568阅读资源/figures/p1185-fig03.webp\" loading=\"lazy\" decoding=\"async\" alt=\"图167.4\" width=\"973\" height=\"60\"><\/button><figcaption>图167.4 · 点击放大<\/figcaption><\/figure>\n<p class=\"body-copy\">Makefile 文件内容如代码清单167.8 所示。<\/p>\n<p class=\"caption\">代码清单167.8<\/p>\n<div class=\"code-box\" data-start=\"1\" data-end=\"9\" data-contiguous=\"true\"><div class=\"code-bar\"><span>Makefile<\/span><button type=\"button\" class=\"copy-code\">复制代码<\/button><\/div><pre tabindex=\"0\"><code><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">1<\/span><span class=\"source-line\">export ARCH=arm64#设置平台架构<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">2<\/span><span class=\"source-line\">export CROSS_COMPILE=aarch64-linux-gnu-#交叉编译器前缀<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">3<\/span><span class=\"source-line\">obj-m += ft5x06_driver.o    #此处要和你的驱动源文件同名<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">4<\/span><span class=\"source-line\">KDIR :=/home/topeet/Linux/linux_sdk/kernel    #这里是你的内核目录<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">5<\/span><span class=\"source-line\">PWD ?= $(shell pwd)<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">6<\/span><span class=\"source-line\">all:<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">7<\/span><span class=\"source-line\">\tmake -C $(KDIR) M=$(PWD) modules    #make 操作<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">8<\/span><span class=\"source-line\">clean:<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">9<\/span><span class=\"source-line\">\tmake -C $(KDIR) M=$(PWD) clean    #make clean 操作<\/span><\/span><\/code><\/pre><p class=\"code-note\">原书第 1185 页 · 行号不参与复制 · <button type=\"button\" data-original=\"1185\">核对原页<\/button><\/p><\/div>\n<p class=\"body-copy\">在存放ft5x06_driver.c 和Makefile 文件目录下使用make 命令编译驱动程序，编译完成如图167.5 所示。<\/p>\n<figure class=\"book-figure\"><button type=\"button\" class=\"zoom-image\" aria-label=\"放大图167.5\"><img src=\"3568阅读资源/figures/p1185-fig04.webp\" loading=\"lazy\" decoding=\"async\" alt=\"图167.5\" width=\"975\" height=\"183\"><\/button><figcaption>图167.5 · 点击放大<\/figcaption><\/figure>\n<p class=\"body-copy\">编译成功后得到ft5x06_driver.ko 文件，如图167.6 所示。<\/p>"},{"n":1186,"html":"<figure class=\"book-figure\"><button type=\"button\" class=\"zoom-image\" aria-label=\"放大图167.6\"><img src=\"3568阅读资源/figures/p1186-fig01.webp\" loading=\"lazy\" decoding=\"async\" alt=\"图167.6\" width=\"974\" height=\"86\"><\/button><figcaption>图167.6 · 点击放大<\/figcaption><\/figure>\n<span class=\"bookmark-anchor\" id=\"b990\"><\/span><h4 class=\"book-heading\">167.3.2 运行测试<\/h4>\n<p class=\"body-copy\">将本章节编译好的ft5x06_device.ko 和ft5x06_driver.ko 驱动文件拷贝到开发板上。然后分别使用insmod ft5x06_device.ko 和insmod ft5x06_driver.ko 命令加载这两个驱动程序，加载完成如图167.7 所示。<\/p>\n<figure class=\"book-figure\"><button type=\"button\" class=\"zoom-image\" aria-label=\"放大图167.7\"><img src=\"3568阅读资源/figures/p1186-fig02.webp\" loading=\"lazy\" decoding=\"async\" alt=\"图167.7\" width=\"974\" height=\"102\"><\/button><figcaption>图167.7 · 点击放大<\/figcaption><\/figure>\n<p class=\"body-copy\">由图167.7 可以看到在ft5x06_device.ko 驱动加载成功之后，成功在i2c1 控制器注册了地址为0x38 的设备，然后加载ft5x06_device.ko 驱动，成功打印了在probe 函数中的打印，证明ft5x06对应的i2c client 和ft5x06_driver 驱动匹配成功了，而这里打印了两遍probe 函数中的打印是因为驱动还会和用设备树编写的i2c client 进行匹配，如果将使用设备树编写的i2c client 删除则只会执行一次probe 函数。<\/p>\n<p class=\"body-copy\">实验成功后使用rmmod ft5x06_driver.ko 和rmmod ft5x06_device.ko 命令进行驱动模块的卸载，如图167.8 所示。<\/p>\n<figure class=\"book-figure\"><button type=\"button\" class=\"zoom-image\" aria-label=\"放大图167.8\"><img src=\"3568阅读资源/figures/p1186-fig03.webp\" loading=\"lazy\" decoding=\"async\" alt=\"图167.8\" width=\"973\" height=\"93\"><\/button><figcaption>图167.8 · 点击放大<\/figcaption><\/figure>"},{"n":1187,"html":"<span class=\"bookmark-anchor\" id=\"b991\"><\/span><h2 class=\"book-heading\">第168 章完善ft5x06 设备节点和驱动<\/h2>\n<p class=\"body-copy\">本章在前面i2c client 和i2c driver 代码的基础上继续编写ft5x06 的对应的i2c client 与i2 c driver，即ft5x06 的设备节点与驱动程序<\/p>\n<span class=\"bookmark-anchor\" id=\"b992\"><\/span><h3 class=\"book-heading\">168.1 完善ft5x06 设备节点<\/h3>\n<p class=\"body-copy\">本实验修改完成的设备树存储在网盘iTOP-RK3568开发板\\07_学习教程配套资料\\03_Linu x 驱动配套资料\\04_Linux 驱动程序\\104_ft5x06_03\\01_修改完成的设备树路径下。<\/p>\n<p class=\"body-copy\">ft5x06 触摸芯片除需要使用i2c 接口，还需要两个GPIO 引脚分别作为中断引脚和复位引脚，ft5x06 触摸芯片使用的i2c 接口与GPIO 引脚介绍如图168.1 所示。<\/p>\n<figure class=\"book-figure\"><button type=\"button\" class=\"zoom-image\" aria-label=\"放大图168.1\"><img src=\"3568阅读资源/figures/p1187-fig01.webp\" loading=\"lazy\" decoding=\"async\" alt=\"图168.1\" width=\"974\" height=\"175\"><\/button><figcaption>图168.1 · 点击放大<\/figcaption><\/figure>\n<p class=\"body-copy\">根据图168.1 中引脚使用情况完善设备树中的ft5x06 的设备节点，完善后的ft5x06 设备节点如代码清单168.1 所示。<\/p>\n<p class=\"caption\">代码清单168.1<\/p>\n<div class=\"code-box\" data-start=\"1\" data-end=\"14\" data-contiguous=\"true\"><div class=\"code-bar\"><span>代码清单<\/span><button type=\"button\" class=\"copy-code\">复制代码<\/button><\/div><pre tabindex=\"0\"><code><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">1<\/span><span class=\"source-line\">&amp;i2c1 {<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">2<\/span><span class=\"source-line\">    status = &quot;okay&quot;;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">3<\/span><span class=\"source-line\"><\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">4<\/span><span class=\"source-line\">    myft5x06: my-ft5x06@38 {<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">5<\/span><span class=\"source-line\">        compatible = &quot;my-ft5x06&quot;;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">6<\/span><span class=\"source-line\">        reg = &lt;0x38&gt;;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">7<\/span><span class=\"source-line\">        reset-gpios = &lt;&amp;gpio0 RK_PB6 GPIO_ACTIVE_LOW&gt;;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">8<\/span><span class=\"source-line\">        interrupt-parent = &lt;&amp;gpio3&gt;;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">9<\/span><span class=\"source-line\">        interrupts-gpio = &lt;&amp;gpio3 RK_PA5 GPIO_ACTIVE_LOW&gt;;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">10<\/span><span class=\"source-line\">        interrupts = &lt;RK_PA5 IRQ_TYPE_LEVEL_LOW&gt;;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">11<\/span><span class=\"source-line\">        pinctrl-names = &quot;default&quot;;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">12<\/span><span class=\"source-line\">        pinctrl-0 = &lt;&amp;myft5x06_pins&gt;;<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">13<\/span><span class=\"source-line\">    };<\/span><\/span><span class=\"code-line\"><span class=\"line-no\" aria-hidden=\"true\">14<\/span><span class=\"source-line\">};<\/span><\/span><\/code><\/pre><p class=\"code-note\">原书第 1187 页 · 行号不参与复制 · <button type=\"button\" data-original=\"1187\">核对原页<\/button><\/p><\/div>"}]});
